local n=arg[1]; if not n then for _,x in ipairs(peripheral.getNames()) do if peripheral.hasType(x,"inventory") then n=x break end end end; if not n or not peripheral.hasType(n,"inventory") then print("Inventory not found.") return end; local p=peripheral.wrap(n); local used,total=0,0; for _,v in pairs(p.list()) do used=used+1; total=total+v.count end; print(("Inventory %s: %d/%d slots, %d items"):format(n,used,p.size(),total))